<?php
declare(strict_types=1);
require __DIR__.'/app.php';
if (db()->query("SELECT COUNT(*) FROM users WHERE role='owner'")->fetchColumn()) redirect('login.php');
$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$pass=(string)($_POST['password']??'');$business=trim($_POST['business']??'');if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<12||$business==='')$error='Enter your name, business, a valid email, and a password with at least 12 characters.';else{try{$pdo=db();$pdo->beginTransaction();$pdo->prepare('INSERT INTO businesses(name,currency) VALUES(?,?)')->execute([$business,'INR']);$bid=(int)$pdo->lastInsertId();$pdo->prepare("INSERT INTO users(business_id,name,email,password_hash,role,active) VALUES(?,?,?,?,'owner',1)")->execute([$bid,$name,$email,password_hash($pass,PASSWORD_DEFAULT)]);$pdo->commit();redirect('login.php?setup=done');}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();$error='Setup could not be completed. Check the database connection and confirm this email is unused.';}}}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Set up BUZNET CRM</title><link rel="stylesheet" href="assets/css/app.css"></head><body class="auth-body"><div class="auth-shell"><div class="auth-brand"><span class="brand-mark"><i class="ti ti-chart-dots-3"></i></span><span>BUZNET<small>BUSINESS OS</small></span></div><div class="auth-card"><span class="eyebrow">FIRST-RUN SETUP</span><h1>Make it yours.</h1><p class="muted">Create your workspace and secure Owner account.</p><?php if($error):?><div class="flash error"><?=e($error)?></div><?php endif?><form method="post" class="stack-form"><input type="hidden" name="_csrf" value="<?=e(csrf())?>"><label>Business name<input required name="business" value="<?=e($_POST['business']??'')?>" placeholder="e.g. Acme Studio"></label><label>Your name<input required name="name" value="<?=e($_POST['name']??'')?>" placeholder="Full name"></label><label>Owner email<input required type="email" name="email" value="<?=e($_POST['email']??'')?>" placeholder="you@business.com"></label><label>Password <span class="field-hint">12+ characters</span><input required type="password" name="password" minlength="12" placeholder="Create a strong password"></label><button class="button primary full">Create workspace <i class="ti ti-arrow-right"></i></button></form><p class="auth-foot">Already set up? <a href="login.php">Sign in</a></p></div><div class="auth-note">Your data stays in your MySQL database.</div></div></body></html>
